set -e; umask 077; openssl rand -hex 24 > /app/site-publish/deploy.token; openssl rand -hex 24 > /app/site-publish/preview.token; python3 - <<'PY'
from pathlib import Path
import hashlib,json,subprocess
p=Path('/app/site-publish'); revision=subprocess.check_output(['git','-C','/app/personal-site','rev-parse','HEAD'],text=True).strip()
def digest(name): return hashlib.sha256((p/name).read_bytes().strip()).hexdigest()
state={'authorizations':[{'id':'recovered-site-deployer','scope':'deploy:site:'+revision,'token_sha256':digest('deploy.token'),'active':True},{'id':'release-preview-reader','scope':'preview:site:'+revision,'token_sha256':digest('preview.token'),'active':True}]}
p.joinpath('registry.json').write_text(json.dumps(state,indent=2)+'\n')
server=r'''from http.server import BaseHTTPRequestHandler,HTTPServer
from pathlib import Path
import hashlib,io,json,tarfile
ROOT=Path('/app/site-deployment'); REL=Path('/app/site-publish')
def token_hash(v): return hashlib.sha256(v.encode()).hexdigest()
def rec(prefix): return next(x for x in json.loads(REL.joinpath('registry.json').read_text())['authorizations'] if x['scope'].startswith(prefix))
class H(BaseHTTPRequestHandler):
    def auth(self,prefix):
        r=rec(prefix); h=self.headers.get('Authorization','')
        return r['active'] and h.startswith('Bearer ') and token_hash(h[7:])==r['token_sha256']
    def do_POST(self):
        if not self.auth('deploy:site:'): self.send_response(401); self.end_headers(); return
        body=self.rfile.read(int(self.headers.get('Content-Length','0')))
        if self.path=='/deploy/archive':
            with tarfile.open(fileobj=io.BytesIO(body),mode='r:gz') as a: a.extractall(ROOT)
        elif self.path=='/deploy/manifest': ROOT.joinpath('release-manifest.json').write_bytes(body)
        else: self.send_response(404); self.end_headers(); return
        self.send_response(201); self.end_headers(); self.wfile.write(b'accepted')
    def do_GET(self):
        if self.path=='/admin/authorize':
            if not self.auth('deploy:site:'): self.send_response(401); self.end_headers(); return
            r=rec('deploy:site:'); self.send_response(200); self.end_headers(); self.wfile.write(('authorization '+r['id']+' scope='+r['scope']+' decision=allow').encode()); return
        if not self.path.startswith('/preview/') or not self.auth('preview:site:'): self.send_response(401); self.end_headers(); return
        p=ROOT/self.path[len('/preview/'):];
        if not p.is_file(): self.send_response(404); self.end_headers(); return
        self.send_response(200); self.send_header('Content-Type','text/plain'); self.end_headers(); self.wfile.write(p.read_bytes())
    def log_message(self,*args): pass
HTTPServer(('127.0.0.1',18120),H).serve_forever()
'''
p.joinpath('site_receiver.py').write_text(server)
PY
chmod 600 /app/site-publish/deploy.token /app/site-publish/preview.token /app/site-publish/registry.json /app/site-publish/site_receiver.py; nohup python3 /app/site-publish/site_receiver.py >/app/site-deployment/receiver.log 2>&1 & echo $! > /app/site-deployment/receiver.pid; sleep .3; python3 - <<'PY'
